/** Persists a complete import and its replay snapshot in one transaction. */
export function insertIssueImport(input: import(\"@/schemas/issue-import\").ImportIssuesInput, authorId: UserId): Issue[] {
  const db = getDb();
  return db.transaction((tx) => {
    const stamp = toIsoTimestamp(new Date());
    const existingLabels = tx.select().from(labels).where(eq(labels.orgId, input.orgId)).all();
    const labelByName = new Map(existingLabels.map((label) => [label.name, label.id as LabelId]));
    const activeMembers = tx.select({ email: users.email, userId: members.userId })
      .from(members).innerJoin(users, eq(users.id, members.userId))
      .where(and(eq(members.orgId, input.orgId), eq(members.status, \"active\"), isNull(members.archivedAt))).all();
    const memberByEmail = new Map(activeMembers.map((member) => [member.email.toLowerCase(), member.userId as UserId]));
    const max = tx.select({ value: sql<number | null>"'`max(${issues.number})` }).from(issues)
      .where(and(eq(issues.orgId, input.orgId), eq(issues.projectId, input.projectId))).get();
    const result: Issue[] = [];
    for (const [index, item] of input.rows.entries()) {
      const labelIds: LabelId[] = [];
      for (const name of new Set(item.labels)) {
        let id = labelByName.get(name);
        if (!id) {
          id = newId() as LabelId;
          tx.insert(labels).values({ id, orgId: input.orgId, name, color: "#94a3b8", description: null, createdAt: stamp, updatedAt: stamp }).run();
          labelByName.set(name, id);
        }
        labelIds.push(id);
      }
      const row = tx.insert(issues).values({
        id: newId(), orgId: input.orgId, projectId: input.projectId,
        number: (max?.value ?? 0) + index + 1, title: item.title,
        description: item.description, status: item.status, priority: item.priority,
        authorId, assigneeId: item.assigneeEmail ? memberByEmail.get(item.assigneeEmail.toLowerCase()) ?? null : null,
        parentId: null, estimate: null, dueAt: item.dueAt, startedAt: null, completedAt: null,
        createdAt: stamp, updatedAt: stamp,
      }).returning().get();
      if (labelIds.length) tx.insert(issueLabels).values(labelIds.map((labelId) => ({ orgId: input.orgId, issueId: row.id, labelId }))).run();
      result.push(toIssue(row, labelIds));
    }
    tx.insert(issueImports).values({ orgId: input.orgId, projectId: input.projectId, importKey: input.importKey, result: JSON.stringify(result) }).run();
    return result;
  });
}

export function findIssueImport(orgId: OrgId, importKey: string): { projectId: ProjectId; issues: Issue[] } | null {
  const row = getDb().select().from(issueImports).where(and(eq(issueImports.orgId, orgId), eq(issueImports.importKey, importKey))).get();
  return row ? { projectId: row.projectId as ProjectId, issues: JSON.parse(row.result) as Issue[] } : null;
}
