export async function importIssues(actor: Actor, input: ImportIssuesInput): Promise<IssueImportResult> {
  assertOrgScope(actor, input.orgId);
  const previous = issueRepo.findIssueImport(input.orgId, input.importKey);
  const projectId = previous?.projectId ?? input.projectId;
  const project = requireFound(await projectRepo.findProjectById(input.orgId, projectId), \"Project\", projectId);
  assertNotArchived(\"Project\", project.id, project);
  assertCan(actor, \"issue:create\", projectResource(project));
  if (previous) return { importKey: input.importKey, projectId, issues: previous.issues, replayed: true };
  const org = requireFound(await orgRepo.findOrgById(input.orgId), \"Organization\", input.orgId);
  const used = await issueRepo.countIssues(input.orgId, input.projectId);
  if (wouldExceedLimit(org.plan, \"issuesPerProject\", used + input.rows.length - 1)) {
    throw new Error("'`Plan ${org.plan} allows no more issues in project ${project.key}`);
  }
  const verdict = await consumeRateLimit(input.orgId, "issue:create", input.rows.length);
  if (!verdict.allowed) throw new Error(`Issue rate limit reached; try again after ${verdict.resetAt}`);
  const issues = issueRepo.insertIssueImport(input, actor.userId);
  await emit("issues.imported", { ...actorEnvelope(actor), projectId: input.projectId, importKey: input.importKey, issueIds: issues.map((issue) => issue.id) });
  return { importKey: input.importKey, projectId: input.projectId, issues, replayed: false };
}
